from os.path import isdir, isfile
import shutil
from tempfile import mkdtemp

from .adaptation_versions import AdaptationVersions
from .scfd import Scfd
from .sutool import SUTool, InvalidSUToolInput


class SUToolWrapper(object):
    """A wrapper for SUTool that automatically gets SCFDs and AdaptationVersions from eNB or from a SW package."""

    def __init__(self, installation_dir=SUTool.DEFAULT_INSTALLATION_DIR):
        self.installation_dir = installation_dir

    def migrate_scfc_locally(self, scfc_path, output_path, scfds_source, enb_ip='192.168.255.1', log_path=''):
        """Get SCFDs and optionally AdapatationVersions from the scfds_source and run SUTool."""
        scfd_dir, adaptation_versions_path = self._get_required_files(scfds_source, enb_ip)
        try:
            return SUTool(self.installation_dir).migrate_scfc_locally(scfc_path, output_path, scfd_dir, log_path, adaptation_versions_path)
        finally:
            if scfd_dir != scfds_source:
                self._delete_dir(scfd_dir)

    def _get_required_files(self, scfds_source, enb_ip):
        if isdir(scfds_source):
            return self._get_files_from_dir(scfds_source)
        elif isfile(scfds_source):
            return self._get_files_from_enb_sw_zip(scfds_source)
        elif self._clean_constant(scfds_source) == 'activepartition':
            return self._get_files_from_enb_partition(enb_ip, partition='active')
        elif self._clean_constant(scfds_source) == 'passivepartition':
            return self._get_files_from_enb_partition(enb_ip, partition='passive')
        else:
            raise InvalidSUToolInput(scfds_source + ' is not a valid source for SCFD files for SUTool')

    def _get_files_from_dir(self, scfds_source):
        adaptation_versions_path = AdaptationVersions().find_in_directory(scfds_source)
        return scfds_source, adaptation_versions_path

    def _get_files_from_enb_sw_zip(self, sw_package_path):
        temp_scfd_dir = mkdtemp()
        try:
            Scfd().get_all_from_enb_sw_zip(sw_package_path, temp_scfd_dir)
            adaptation_versions_path = AdaptationVersions().get_from_enb_sw_zip(sw_package_path, temp_scfd_dir)
        except:
            self._delete_dir(temp_scfd_dir)
            raise
        else:
            return temp_scfd_dir, adaptation_versions_path

    def _get_files_from_enb_partition(self, enb_ip, partition):
        temp_scfd_dir = mkdtemp()
        try:
            Scfd().get_all_from_enb(enb_ip, partition, output_dir=temp_scfd_dir)
            adaptation_versions_path = AdaptationVersions().get_from_enb(enb_ip, partition, output_dir=temp_scfd_dir)
        except:
            self._delete_dir(temp_scfd_dir)
            raise
        else:
            return temp_scfd_dir, adaptation_versions_path

    def _clean_constant(self, constant_string):
        return constant_string.lower().replace(' ', '').replace('_', '')

    def _delete_dir(self, path):
        shutil.rmtree(path, ignore_errors=True)
